#!/usr/bin/env python3
"""Rebuild the illustrated Portuguese installation guide using ReportLab."""
import os
from pathlib import Path
from xml.sax.saxutils import escape
import json
import re
import shutil
import subprocess
import sys
import runpy
from reportlab.pdfgen import canvas
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, Flowable, KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.utils import ImageReader
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.pagesizes import A4
ROOT=Path(__file__).resolve().parents[1]
WHATSAPP_ONLY='--zernio-only' in sys.argv or '--meta-only' in sys.argv
OUT=ROOT/('output/pdf/wabotia-zernio-whatsapp.pdf' if WHATSAPP_ONLY else 'output/pdf/wabotia-instalacao.pdf'); OUT.parent.mkdir(parents=True,exist_ok=True)
SHOTS=ROOT/'docs/screenshots'
font_root=next((d for d in [Path(os.environ.get('WABOTIA_GUIDE_FONTS','')),Path('/usr/share/fonts/truetype/dejavu'),Path.home()/'.wabotia-tools/fonts/dejavu'] if (d/'DejaVuSans.ttf').is_file()),None)
if font_root is None: sys.exit('Fontes DejaVu não encontradas. Indique a pasta em WABOTIA_GUIDE_FONTS.')
for name,file in [('Sans','DejaVuSans.ttf'),('SansBold','DejaVuSans-Bold.ttf'),('Mono','DejaVuSansMono.ttf'),('Serif','DejaVuSerif.ttf')]:
    pdfmetrics.registerFont(TTFont(name,str(font_root/file)))
pdfmetrics.registerFontFamily('Sans',normal='Sans',bold='SansBold',italic='Sans',boldItalic='SansBold')
GREEN=colors.HexColor('#173b30'); INK=colors.HexColor('#203b32'); MUTE=colors.HexColor('#62766b'); LIME=colors.HexColor('#d6ed9e'); CREAM=colors.HexColor('#f6f8f1'); LINE=colors.HexColor('#dfe6d7')
W,H=A4; M=44; CW=W-2*M
styles={
 'body':ParagraphStyle('body',fontName='Sans',fontSize=10.4,leading=15.2,textColor=INK,spaceAfter=9),
 'small':ParagraphStyle('small',fontName='Sans',fontSize=8.6,leading=12.1,textColor=MUTE,spaceAfter=7),
 'title':ParagraphStyle('title',fontName='SansBold',fontSize=26,leading=31,textColor=GREEN,spaceAfter=13),
 'sub':ParagraphStyle('sub',fontName='SansBold',fontSize=13.2,leading=18,textColor=GREEN,spaceBefore=8,spaceAfter=8),
 'eyebrow':ParagraphStyle('eyebrow',fontName='SansBold',fontSize=9,leading=13,textColor=MUTE,spaceAfter=10),
 'code':ParagraphStyle('code',fontName='Mono',fontSize=8.3,leading=12.4,textColor=GREEN,backColor=colors.HexColor('#edf2e3'),borderPadding=10,spaceBefore=5,spaceAfter=13),
 'caption':ParagraphStyle('caption',fontName='Sans',fontSize=8,leading=11,textColor=MUTE,spaceBefore=6,spaceAfter=13),
 'cover':ParagraphStyle('cover',fontName='SansBold',fontSize=39,leading=45,textColor=GREEN,spaceAfter=18),
}
story=[]
step_no=0
# Referências de página: o texto usa {pg:chave}; a página de cada capítulo é
# medida numa passada e aplicada na seguinte, até as duas coincidirem.
PASS=int(os.environ.get('WABOTIA_GUIDE_PASS','1'))
PAGES_FILE=OUT.with_suffix('.pages.json')
PAGES=json.loads(PAGES_FILE.read_text(encoding='utf-8')) if PASS>1 and PAGES_FILE.is_file() else {}
SEEN={}
def R(text):return re.sub(r'\{pg:([a-z0-9-]+)\}',lambda m:str(PAGES.get(m.group(1),'00')),str(text))
class Mark(Flowable):
    def __init__(self,key):Flowable.__init__(self);self.key=key;self.width=self.height=0
    def draw(self):SEEN[self.key]=self.canv.getPageNumber()
chapter=1
def p(text,style='body'): story.append(Paragraph(R(text),styles[style]))
def title(n,text,key=None):
    # n é ignorado: a numeração segue a ordem dos capítulos.
    global step_no,chapter
    step_no=0;chapter+=1
    if story:story.append(PageBreak())
    p(f'GUIA DE INSTALAÇÃO / {chapter:02d}', 'eyebrow');p(text,'title')
    if key:story.append(Mark(key))
def sub(text):p(text,'sub')
def steps(items):
    global step_no
    for text in items:
        step_no+=1
        p(f'<b>{step_no}.</b> {text}')
def code(text):p(escape(text).replace('\n','<br/>').replace(' ','&#160;'),'code')
def box(text):
    t=Table([[Paragraph(R(text),styles['body'])]],colWidths=[CW]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#eaf2dc')),('BOX',(0,0),(-1,-1),0.6,LINE),('LEFTPADDING',(0,0),(-1,-1),13),('RIGHTPADDING',(0,0),(-1,-1),13),('TOPPADDING',(0,0),(-1,-1),11),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.extend([t,Spacer(1,12)])
def table(rows,widths=None):
    data=[[Paragraph(R(v),styles['small']) for v in row] for row in rows]
    t=Table(data,colWidths=widths or [CW*.33,CW*.67],hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),LIME),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,-1),.4,LINE),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),4)]));story.extend([t,Spacer(1,12)])
class Shot(Flowable):
    def __init__(self,name,width=CW,crop=None):
        Flowable.__init__(self);self.img=ImageReader(str(SHOTS/name));self.iw,self.ih=self.img.getSize();self.crop=crop or (0,0,self.iw,self.ih);self.width=width;self.height=width*self.crop[3]/self.crop[2];self.hAlign='CENTER'
    def draw(self):
        x,y,w,h=self.crop;s=self.width/w;c=self.canv;c.saveState();path=c.beginPath();path.rect(0,0,self.width,self.height);c.clipPath(path,stroke=0);c.drawImage(self.img,-x*s,(y+h-self.ih)*s,width=self.iw*s,height=self.ih*s);c.restoreState();c.setStrokeColor(LINE);c.rect(0,0,self.width,self.height,stroke=1,fill=0)
def shot(name,caption,width=CW,crop=None):story.extend([Shot(name,width,crop),Paragraph(caption,styles['caption'])])
def link(label,url):return f'<link href="{url}" color="#34684f"><u>{label}</u></link>'
append_zernio_chapter=runpy.run_path(str(ROOT/'scripts/zernio-guide-pages.py'))['append_zernio_chapter']
# Capa
p('WABOTIA / CÓDIGO ABERTO / VERSÃO 0.16.6','eyebrow')
p('Seu atendimento.<br/>Bem conectado.','cover')
p('Guia para instalar na Cloudflare pelo navegador,<br/>conectar o Hermes e preparar sua equipe.','sub')
shot('01-inicio.jpg','Página inicial do Wabotia. As ilustrações e conversas de exemplo são fictícias.',width=430)
p(link('Instalar agora em wabotia.queven.app/instalar','https://wabotia.queven.app/instalar'))
p('Edição de 14/11/2026. Leia na ordem. A instalação é feita pelo navegador, sem terminal. O painel fica na sua conta Cloudflare; o Hermes continua no computador ou servidor que você escolher.','small')

title(0,'Do zero ao atendimento','visao')
p('Você não precisa instalar programas no computador, criar conta no GitHub nem ter domínio próprio. A instalação cria tudo na sua conta Cloudflare e as próximas versões chegam pelo painel.')
steps(['<b>Prepare a Cloudflare.</b> Ative o R2 e copie o ID da conta. Página {pg:r2}.','<b>Crie o token</b> pelo link que já abre o formulário preenchido. Página {pg:token}.','<b>Instale pelo navegador.</b> Informe o ID, o token e um nome; baixe as chaves e aguarde alguns minutos. Páginas {pg:instalar} e {pg:instalar2}.','<b>Crie seu administrador</b> pelo botão exibido ao final e conheça o painel. Páginas {pg:conta} e {pg:painel}.','<b>Conecte o Hermes pelo plugin.</b> Um comando na máquina do Hermes, sem túnel, domínio ou porta aberta. Páginas {pg:plugin} a {pg:plugin4}.','<b>Conecte o WhatsApp</b> pela Zernio, página {pg:zernio}, ajuste as regras de atendimento, página {pg:regras}, e faça a primeira conversa, página {pg:conversa}.'])
box('<b>Vai reinstalar?</b> Use um nome novo, como wabotia-atendimento. A instalação nova começa vazia e não importa o histórico antigo. Mantenha a anterior até conferir o novo painel. O roteiro de transição está na página {pg:reinstalar}.')
sub('Caminhos alternativos')
p('Se preferir que o token da Cloudflare nunca passe pelo site oficial, use o <b>instalador pelo terminal</b>, páginas {pg:terminal} a {pg:terminal-fim}. Se o seu Hermes já está ligado por <b>túnel Cloudflare</b>, ou você precisa desse modo, o roteiro continua nas páginas {pg:tunel} a {pg:tunel-fim}. Conexões por túnel já criadas não mudam.')
p('Depois de instalar: atualizações na página {pg:atualizar}, contatos na página {pg:agenda}, recursos do WhatsApp na página {pg:whats} e Integração Zernio com vários números na página {pg:roteador}.','small')

title(0,'Para que serve a Cloudflare?','cloudflare')
p('Ela mantém o Wabotia disponível na internet e guarda seus dados. Cada serviço cuida de uma parte. O Hermes continua executando os bots na máquina ou VPS escolhida.')
table([['Serviço','Função no seu atendimento'],['Workers','Executa o painel web, a API e as regras do atendimento. O painel continua acessível com seu computador desligado.'],['D1','Banco de dados: guarda usuários, configurações, conversas, protocolos e registros.'],['R2','Armazena documentos, imagens, áudios e anexos. Um bucket é a área onde esses arquivos ficam guardados. O instalador cria um bucket privado.'],['Durable Objects e alarmes','Organizam o processamento por perfil e retomam tarefas pendentes, mantendo a ordem e evitando operações duplicadas.'],['API da Cloudflare','Recebe os arquivos do instalador e publica as atualizações solicitadas no painel, sem repositório próprio ou Builds.'],['Workers Secrets','Guardam MASTER_KEY, SETUP_TOKEN e o token de atualização no ambiente protegido do seu Worker.']],widths=[CW*.30,CW*.70])
box('<b>Exemplo:</b> a mensagem chega ao Worker; o registro vai para o D1 e o anexo para o R2. Durable Objects organizam o trabalho. Para executar um bot, o Worker entrega o pedido ao plugin instalado no Hermes, que mantém a conexão aberta de dentro para fora.')
p('Com o plugin, você <b>não precisa</b> de Zero Trust, Access, Tunnel, cloudflared, DNS nem domínio próprio. Esses serviços só entram no modo alternativo por túnel, páginas {pg:tunel} a {pg:tunel-fim}.')
p('O plano do site/domínio, Workers e a assinatura R2 são configurações distintas. Ativar um deles não ativa os demais. D1 e Durable Objects seguem o plano Workers. Workers Paid é a referência de produção; confira planos e condições vigentes na Cloudflare.','small')

title(0,'Ative o R2 e copie o ID da conta','r2')
shot('53-cloudflare-conta.jpg','Recortes do painel da Cloudflare em português: o menu de armazenamento e o cartão Detalhes da conta. Os identificadores foram cobertos.',width=300)
steps(['Entre em '+link('dash.cloudflare.com','https://dash.cloudflare.com')+' e selecione a conta onde o Wabotia vai ficar. Se ainda não tem conta, crie uma gratuitamente.','No menu lateral, abra <b>Armazenamento e bancos de dados &gt; Armazenamento de objetos R2</b>. Se aparecer a tela de adesão, conclua a ativação: a Cloudflare pede dados de cobrança mesmo para usar a franquia gratuita. Confira termos e valores antes de confirmar.','Confirme que aparece a lista de buckets ou o botão <b>Criar bucket</b>. Não crie nenhum bucket: o instalador cria o dele.','Na mesma tela, à direita, em <b>Detalhes da conta</b>, copie o <b>ID da conta</b>: 32 letras e números. Ele também aparece na barra de endereço, logo depois de dash.cloudflare.com/. Não use o ID de zona de um domínio.'])
box('<b>Sem o R2 ativo a instalação não começa.</b> A conferência inicial avisa e não cria nada. O D1 (Banco de dados SQLite D1, no mesmo menu) já faz parte do plano Workers e não tem adesão separada. Você não precisa criar banco nem gerar chaves S3.')
p('O R2 inclui uma franquia mensal gratuita e pode cobrar pelo uso excedente. Gratuito não significa armazenamento ilimitado. Se o painel estiver em inglês, os nomes são Storage &amp; databases, R2 object storage e Account ID.','small')
p(link('Ativação oficial do R2','https://developers.cloudflare.com/r2/get-started/')+' · '+link('Preços R2','https://developers.cloudflare.com/r2/pricing/')+' · '+link('Planos D1','https://developers.cloudflare.com/d1/platform/pricing/'),'small')

title(0,'Crie o token pelo link pronto','token')
shot('52-cloudflare-token.jpg','Tela real Criar token aberta pelo link do instalador: nome preenchido e 3 permissões já marcadas em Plataforma do desenvolvedor.',width=CW)
steps(['Abra '+link('wabotia.queven.app/instalar','https://wabotia.queven.app/instalar')+' e clique em <b>abrir a Cloudflare com o token já preenchido</b>. A Cloudflare abre a tela <b>Criar token</b> com o nome Wabotia instalação e as três permissões necessárias: Workers Scripts, D1 e Workers R2 Storage, todas de edição.','Em <b>Políticas</b>, troque <b>Todas as contas</b> pela conta onde vai instalar. Assim o token não alcança outras contas suas.','Em <b>Expiração do token</b>, escolha a validade. O token fica guardado no seu Worker para as atualizações pelo painel; se ele expirar, basta cadastrar outro, página {pg:renovar}.','Clique <b>Continuar até o resumo</b>, confira e confirme a criação. Copie o valor exibido: a Cloudflare mostra o token uma única vez. Guarde-o até colar no instalador.'])
box('Não use a Global API Key. No instalador pelo navegador, o token passa pelo servidor do site oficial a cada passo, apenas para ser repassado à Cloudflare; ele não é guardado nem registrado lá. Se preferir que nunca passe pelo site, use o instalador pelo terminal, página {pg:terminal}.')
p('Em telas em inglês: Policies, All accounts, Token expiration e Continue to summary. O token para o modo túnel do Hermes é outro, com permissões diferentes, página {pg:tunel-deploy}.','small')

title(0,'Instale pelo navegador','instalar')
shot('51-instalar-dados.jpg','wabotia.queven.app/instalar, etapa 2. O campo do token não mostra o que foi colado.',width=400)
steps(['Volte à aba '+link('wabotia.queven.app/instalar','https://wabotia.queven.app/instalar')+'. Em <b>Account ID da Cloudflare</b>, cole o ID da conta copiado na página {pg:r2}.','Em <b>Token de API da Cloudflare</b>, cole o token criado na página {pg:token}.','Em <b>Nome novo para a instalação</b>, use letras minúsculas, números e hífen, como wabotia-atendimento. O nome vira o endereço: nome.sua-conta.workers.dev. Não reutilize o nome de uma instalação existente.','Leia o aviso sobre o token, marque <b>Entendi e quero instalar por aqui</b> e clique <b>Conferir a conta</b>.'])
p('A conferência valida o token, o R2 e os nomes. <b>Nada é criado nessa etapa.</b> Se algo estiver errado, a página explica o motivo e oferece <b>Corrigir os dados</b>.')
table([['Causa comum','O que fazer'],['R2 ainda não ativado','Conclua a adesão da página {pg:r2} e tente de novo.'],['Token recusado ou sem permissão','Confira se copiou o token inteiro, se ele inclui a conta certa e se não expirou. Crie outro pelo link.'],['Nome já usado','Escolha outro nome. O instalador não substitui um Worker, banco ou bucket existente.']])

title(0,'Guarde as chaves e acompanhe','instalar2')
steps(['Com a conta conferida, aparece <b>3. Guarde as chaves antes de continuar</b>. Clique <b>Baixar chaves</b>. O navegador salva o arquivo <b>nome-chaves.local.json</b>, com MASTER_KEY e SETUP_TOKEN gerados no seu próprio navegador.','Guarde esse arquivo em local privado e faça uma cópia de segurança. A <b>MASTER_KEY</b> protege as credenciais da instalação e não pode ser recuperada depois. Não envie o arquivo a ninguém, nem ao suporte.','Clique <b>Guardei o arquivo, instalar</b>. <b>Não feche a aba.</b> A página mostra as oito etapas abaixo e marca cada uma ao concluir. Costuma levar poucos minutos.'])
table([['Etapa na tela','O que acontece na sua conta'],['Conferir a conta e os nomes','Validação, sem criar nada.'],['Criar o banco de dados','Banco D1 com o nome da instalação.'],['Criar o armazenamento de arquivos','Bucket R2 privado, nome seguido de -media.'],['Preparar o banco','Tabelas da versão oficial mais recente.'],['Enviar os arquivos do painel','Telas do painel e do site da sua instalação.'],['Publicar o Wabotia','Worker com as ligações ao banco, ao bucket e às chaves.'],['Ligar o endereço','Endereço nome.sua-conta.workers.dev.'],['Conferir se está no ar','Teste da instalação publicada.']],widths=[CW*.42,CW*.58])
steps(['Se uma etapa falhar ou a internet cair, clique <b>Tentar este passo de novo</b> sem fechar a aba; a instalação continua de onde parou. Se desistir, apague na Cloudflare o Worker, o banco D1 e o bucket R2 com esse nome antes de instalar novamente.','Ao ver <b>Pronto. O Wabotia está na sua conta.</b>, anote o endereço exibido e clique <b>Criar meu administrador</b>.'])
box('Nada fica instalado no seu computador e ele pode ser desligado depois. O instalador publica a versão oficial mais recente; as próximas chegam por <b>Sistema e atualizações</b>, página {pg:atualizar}.')

title(0,'Sua primeira conta','conta')
p('O botão <b>Criar meu administrador</b> abre <b>SUA_URL/app</b> com o código de instalação já preenchido. A primeira conta é de administrador; as próximas pessoas são cadastradas dentro do painel.')
shot('02-primeira-conta.jpg','Tela de primeira instalação, com os campos vazios. Pelo botão do instalador, o código de instalação já vem preenchido.',width=250,crop=(805,0,425,648))
steps(['Preencha <b>Seu nome</b>, <b>E-mail</b> e uma <b>Senha</b> com pelo menos 12 caracteres. Essa senha é só sua e é diferente das chaves do arquivo.','Se o campo <b>Código de instalação (SETUP_TOKEN)</b> estiver vazio, porque você abriu o endereço direto, copie o valor de SETUP_TOKEN do arquivo de chaves, sem as aspas.','Clique <b>Criar conta e entrar</b>. Guarde o endereço da instalação nos favoritos.'])
p('O código de instalação só serve para criar o primeiro administrador. Depois disso ele não abre mais nada.','small')

title(0,'Conheça o painel','painel')
shot('55-painel-inicio.jpg','Gestão > Início em uma instalação local de demonstração. Pessoas, conversas e números são fictícios.',width=400)
p('A coluna da esquerda tem as áreas de atendimento. Tudo o que é configuração fica em <b>Gestão</b>, que só administradores veem por inteiro. Desde a versão 0.16.1 o painel tem um único modo, com todas as opções visíveis.')
table([['Área','Para que serve'],['Conversas','Receber mensagens, assumir, responder, transferir e concluir.'],['Protocolos','Solicitações com responsável e prazo.'],['Equipe','Presença de cada pessoa e conversa interna com pessoas e bots.'],['Ligações','Histórico de ligações.'],['Contatos','Cadastro de clientes e importação por CSV.'],['Gestão &gt; Automação','Atendente e especialistas, Menus e ações, Modelos de atendimento, Conhecimento e Regras de atendimento.'],['Gestão &gt; WhatsApp e canais','Integração Zernio, Quem atende cada linha, Hermes e canais e Grupos WhatsApp.'],['Gestão &gt; Integrações e Sistema','Sistemas conectados, execuções e entregas, Sistema e atualizações, Pessoas e acessos.']],widths=[CW*.34,CW*.66])
steps(['Em <b>Gestão &gt; Pessoas e acessos</b>, crie uma conta por atendente. Não compartilhe a sua.','Mantenha o atendimento <b>pausado</b> até conectar o Hermes e o WhatsApp. O botão Ativar atendimento fica em Gestão &gt; Regras de atendimento.','Se preferir ser conduzido, abra <b>Gestão &gt; Configuração guiada</b>: ela leva às mesmas telas deste guia.'])

title(0,'Hermes: crie a conexão por plugin','plugin')
p('O plugin é a forma recomendada de ligar os bots do Hermes Agent ao Wabotia. Ele é instalado na máquina do Hermes e abre a conexão <b>de dentro para fora</b>: não há túnel, domínio, porta aberta nem chave do Hermes guardada no Wabotia.')
shot('56-hermes-nova-conexao.jpg','Gestão > Hermes e canais > Nova conexão. Não há endereço nem chave para preencher.',width=270)
steps(['Tenha o Hermes Agent instalado e funcionando em Linux, macOS, WSL2 ou Docker. Ainda não há instalador do plugin para Hermes nativo no Windows.','No Wabotia, abra <b>Gestão &gt; WhatsApp e canais &gt; Hermes e canais</b> e clique <b>Nova conexão</b>.','Dê um nome, como Hermes da VPS. Em <b>Serviço</b>, mantenha Hermes. Em <b>Como ligar ao Hermes</b>, mantenha <b>Plugin no Hermes (recomendado, sem túnel)</b>. Clique <b>Salvar</b>.','A conexão nasce pausada, com o aviso <b>Plugin ainda não pareado</b>. No cartão dela, clique <b>Gerar comando de instalação</b>.'])
box('O modo de ligação é escolhido na criação e não muda depois. Para trocar entre plugin e túnel, crie outra conexão.')

title(0,'Hermes: copie o comando','plugin2')
shot('57-hermes-comando.jpg','Janela Instale o plugin no Hermes, com endereço de exemplo. O código de pareamento vale 15 minutos e só pode ser usado uma vez.',width=235)
steps(['<b>Hermes instalado direto no sistema</b> (Linux, macOS ou WSL2): copie o primeiro comando e cole no terminal dessa máquina, com o mesmo usuário que executa o Hermes. Não use sudo.','<b>Hermes em Docker</b>: abra <b>Meu Hermes roda em Docker</b> e use um dos dois comandos de lá. A página {pg:plugin3} mostra o caminho na Hostinger.','Aguarde as cinco etapas do instalador, de <b>1/5 · Baixando o plugin</b> a <b>5/5 · Ativando o plugin</b>.','<b>Reinicie o gateway do Hermes</b> pelo método que você já usa. O plugin só carrega depois disso. Volte ao Wabotia e clique <b>Concluir</b>.'])
p('O instalador baixa o plugin da sua própria instalação, troca o código por um token guardado na máquina do Hermes, liga a API local somente em 127.0.0.1 e cria a chave do perfil se ela ainda não existir. Chaves existentes são preservadas. Ele não abre portas e não reinicia serviços.','small')
p('Se o código expirar antes de você usar, clique de novo em Gerar comando de instalação. Um código gera um único vínculo.','small')

title(0,'Hermes na Hostinger (Docker)','plugin3')
p('Na VPS da Hostinger com a aplicação Hermes Agent, o Hermes roda dentro de um contêiner. O comando comum responde <b>Hermes não encontrado</b>; use o caminho abaixo.')
shot('54-hostinger-docker.jpg','hPanel > VPS > Gerenciador Docker > Projetos. O link Terminal abre dentro do contêiner; Reiniciar fica no menu de três pontos.',width=CW)
steps(['No hPanel, abra <b>VPS</b>, escolha o servidor e entre em <b>Gerenciador Docker &gt; Projetos</b>. Localize o projeto <b>hermes-agent-…</b> com status Em execução.','Na linha do projeto, clique <b>Terminal</b>. Ele abre <b>dentro do contêiner</b>.','No Wabotia, em Meu Hermes roda em Docker, copie o comando que vem depois de <b>Se o terminal já abre dentro do contêiner</b>. Cole no terminal e pressione Enter.','Ao terminar a etapa 5/5, volte ao Gerenciador Docker, clique nos <b>três pontos</b> do projeto e escolha <b>Reiniciar</b>. Espere voltar a Em execução.'])
sub('Pelo terminal do servidor')
p('Se preferir o <b>Web console</b> (terminal do próprio servidor, fora do contêiner), descubra o nome do contêiner e use o outro comando da janela, trocando CONTEINER por esse nome:')
code('docker ps --format "{{.Names}}"\ndocker restart CONTEINER')
box('O plugin fica na pasta de dados do Hermes (/opt/data), que é um volume: ele continua lá quando o contêiner é atualizado ou recriado. O instalador se recusa a rodar com um usuário diferente do dono dessa pasta, para o Hermes conseguir ler os arquivos.')

title(0,'Hermes: teste e escolha o Atendente','plugin4')
shot('58-hermes-pareado.jpg','Cartão da conexão depois do pareamento, em uma instalação de demonstração.',width=165)
steps(['No cartão da conexão deve aparecer <b>Plugin pareado em</b> seguido do nome da máquina. Clique <b>Testar conexão</b>.','Clique <b>Descobrir bots</b>. Cada perfil do Hermes aparece como um bot. Depois clique <b>Ativar</b>: o cartão passa a Conectado.','Abra <b>Gestão &gt; Automação &gt; Atendente e especialistas</b>. Clique <b>Habilitar</b> no bot que vai falar com o cliente e depois <b>Usar como Bot Atendente</b>.'])
table([['Situação','O que fazer'],['Plugin ainda não pareado','O comando não terminou ou o código expirou. Gere outro comando e repita.'],['Hermes offline','O gateway do Hermes está parado ou não foi reiniciado depois da instalação.'],['Trocar de máquina','Use Parear novamente e rode o novo comando na outra máquina.'],['Suspeita de vazamento','Use Revogar plugin. O vínculo para de funcionar na hora.']])
p('Para incluir outros perfis do Hermes, gere um código novo e acrescente os nomes dos perfis ao final do comando. O uso com vários perfis ainda precisa de validação na sua instalação.','small')
if not WHATSAPP_ONLY:
    append_zernio_chapter(p,title,sub,steps,code,box,table,shot,link,0)
title(0,'Zernio: conexão individual','zernio-conexao')
p('O caminho principal é a Integração Zernio da página {pg:zernio}, que importa todos os telefones da conta. Esta página cobre a conexão individual de um único número, cadastrada em Hermes e canais.')
steps(['Na Zernio, prepare um perfil e conecte seu número WhatsApp Business pelo cadastro guiado.','No Wabotia, abra <b>Gestão &gt; Hermes e canais &gt; Nova conexão</b> e escolha <b>WhatsApp · Zernio</b>. Informe número, ID do perfil Zernio e accountId do WhatsApp.','Preencha a chave API Zernio e um segredo para assinar o webhook. Salve a conexão.','Na Zernio, cadastre a URL exibida no Wabotia e o mesmo segredo. Assine message.received, message.sent, message.delivered, message.read, message.failed e reaction.received.','Clique <b>Testar conexão</b>, ative o canal e teste recebimento, resposta e anexo com um destinatário autorizado.'])
code('https://SUA_URL/webhooks/zernio/ID_DA_CONEXAO')
sub('Janela, consentimento e templates')
p('Fora da janela de atendimento de 24 horas, esta versão permite notificações de protocolo somente com consentimento e template <b>UTILITY aprovado</b>. O corpo deve ter <b>{{1}}</b> para protocolo e <b>{{2}}</b> para andamento. Configure nome e idioma em Regras de atendimento.')
box('<b>Um número, um consumidor.</b> Antes de trocar entre Zernio, QR ou Hermes, pause o antigo, pare o conector correspondente e confira as pendências em Entregas. Ative o novo modo somente depois da reconciliação.')
p('A confirmação perdida de um envio pode produzir estado unknown. Confira no canal antes de autorizar nova tentativa: ela pode duplicar uma mensagem já recebida.','small')
title(0,'QR direto ou WhatsApp Hermes','qr')
sub('QR direto: processo ao lado do Hermes')
steps(['Crie uma conexão <b>WhatsApp · QR direto</b>. Informe o número. Salve e clique <b>Gerar chave do conector</b>. Guarde chave e ID da conexão.','No host que ficará ligado, abra <b>connectors/qr</b>. Copie .env.example para .env e preencha URL HTTPS, ID e chave. Instale e inicie:'])
code('cd connectors/qr\nnpm ci\nnpm start')
steps(['Ative a conexão. O QR aparece no cartão do painel. No WhatsApp do celular, abra <b>Aparelhos conectados</b> e leia o código.','Mantenha o processo ligado. Preserve <b>data/</b>, com sessão e diário; configure reinício e backup. Não precisa abrir portas de entrada nem túnel para esse conector.'])
p('Em Docker, após preencher .env nessa pasta, use <b>docker compose up -d --build</b>. Preserve o volume qr-data ao atualizar. Baileys é um cliente não oficial; o pareamento deve ser validado na sua conta.','small')
sub('WhatsApp que já está ligado no Hermes')
p('Mantenha Meta/QR configurados no Hermes e escolha <b>WhatsApp · pelo Hermes</b> no painel. Esse caminho precisa do transporte mínimo e da extensão compatível de entrada exclusiva no gateway.')
p('Com o gateway parado e o perfil copiado para backup, siga o README de <b>connectors/hermes</b>: conferir a revisão, testar o patch com git apply --check, instalar no perfil existente e habilitar wabotia_transport em in_process. Reinicie pelo processo que já utiliza.')
box('<b>Não misture os caminhos.</b> O WhatsApp direto dispensa esse plugin. A extensão do Hermes requer manutenção técnica e revalidação quando o gateway é atualizado; não aplique em outra revisão sem conferir compatibilidade.')
title(0,'Regras: ausência, protocolo e assinatura','regras')
p('Em <b>Gestão &gt; Automação &gt; Regras de atendimento</b> você define como o Bot Atendente se comporta quando encaminha o cliente para a equipe. As quatro opções abaixo vêm ligadas.')
shot('60-regras-ausencia.jpg','Regras de atendimento, em uma instalação de demonstração.',width=330)
table([['Opção','Ligada','Desligada'],['Abrir protocolo quando a equipe está ausente','Sem ninguém presente, o encaminhamento abre um protocolo e envia a orientação de ausência.','O cliente só é avisado de que a equipe está ausente; nenhum protocolo é aberto.'],['Bot Atendente continua respondendo enquanto a equipe está ausente','Se o cliente escreve depois de encaminhado, o bot responde com o que já foi informado, sem tirar a conversa da fila.','O cliente aguarda a equipe sem novas respostas do bot.'],['Pedir autorização de notificações ao abrir protocolo','Uma vez por conversa, o cliente recebe a pergunta com os botões Autorizo e Não autorizo.','Nenhum pedido é enviado; o consentimento precisa vir de outro registro.'],['Identificar quem escreve nas mensagens ao cliente','Cada mensagem começa com o nome e o tipo: Bruno - Humano ou Bia - IA.','As mensagens seguem sem assinatura.']],widths=[CW*.30,CW*.38,CW*.32])
p('O nome da pessoa vem de Pessoas e acessos; o do bot, de Atendente e especialistas. Menus, botões e avisos automáticos não levam assinatura. Nas linhas da Zernio, o cliente vê <b>digitando...</b> enquanto o bot prepara a resposta; não há o que configurar.')
p('Altere e clique <b>Salvar regras</b>. Na mesma tela ficam as orientações do Bot Atendente, a mensagem de ausência, a avaliação ao concluir e o botão <b>Ativar atendimento</b>.','small')

title(0,'Prepare os bots e os menus','bots')
shot('59-bots.jpg','Atendente e especialistas com bots de demonstração. Um bot é o Atendente; os demais podem ser especialistas.',width=CW)
steps(['Em <b>Atendente e especialistas</b>, habilite os bots descobertos e confirme quem é o <b>Bot Atendente</b>. Modelos e ferramentas de cada bot continuam configurados no Hermes.','Clique <b>Ação de especialista</b>. Escolha o bot, descreva quando consultá-lo e a ação permitida. O Atendente consulta o especialista internamente e responde ao cliente.','Abra <b>Conhecimento</b> e cadastre informações úteis: texto, URL pública, PDF com texto ou DOCX. Espere a importação ficar disponível. Arquivos têm limite de 20 MB.','Em <b>Menus e ações</b>, monte os caminhos do cliente. Em <b>Modelos de atendimento</b> há conjuntos prontos de menus, setores, categorias e prazos para começar.','Em <b>Quem atende cada linha</b>, escolha o bot ou a equipe responsável por cada telefone conectado.','Cadastre as pessoas em <b>Pessoas e acessos</b>. Na área <b>Equipe</b>, cada pessoa informa quando está presente para assumir atendimentos.'])
box('<b>Arquivos de bots:</b> precisam ser exportados como artefatos da API nativa do Hermes. Caminhos locais não viram links públicos. Downloads de uso único interrompidos exigem nova exportação; o Wabotia não os repete automaticamente.')
p('PDF digitalizado sem texto não tem OCR nesta versão. Vídeos precisam de legendas públicas/autorizadas; também é possível importar TXT, VTT ou SRT.','small')

title(0,'Faça a primeira conversa','conversa')
shot('62-conversa.jpg','Área Conversas com mensagens fictícias. A lista mostra fila, responsável e o tempo restante da janela de 24 horas.',width=CW)
steps(['Em Regras de atendimento, clique <b>Ativar atendimento</b>. Use um número de teste autorizado e envie uma pergunta que possa ser respondida com o conhecimento cadastrado.','Confira a resposta do bot e, no WhatsApp, a assinatura no início da mensagem.','Abra a conversa em <b>Conversas</b> e clique <b>Assumir</b>. Responda pelo painel: a resposta automática que estava em preparação é descartada.','Peça ao bot para falar com um atendente sem ninguém presente. Confira o protocolo aberto, a pergunta de autorização com botões e a resposta do bot enquanto a equipe está ausente.','Teste nota interna, anexo, transferência e conclusão. Nota interna não deve ir ao cliente.'])

title(0,'Integre outros sistemas','integrar')
p('Em <b>Gestão &gt; Integrações &gt; Sistemas conectados</b> você autoriza outros programas a usar o Wabotia. A API é para comunicação entre servidores: cada programa usa uma chave própria e só opera os perfis, bots e ações autorizados.')
steps(['Para Vinki ou Fagoo, use <b>Parear</b>: no outro sistema escolha Conectar ao Wabotia, informe o endereço da sua instalação e confirme no painel o código mostrado. As credenciais são trocadas entre os servidores.','Para dar ao Hermes Agent as ferramentas do Wabotia (consultar e responder conversas, abrir protocolos, contatos), use o cartão <b>Ferramentas do Wabotia no Hermes Agent (MCP)</b> e copie a configuração gerada para o Hermes. É um recurso independente do plugin.','Para outro programa, cadastre uma aplicação, escolha as permissões e os bots e gere a chave. Copie o valor exibido para o servidor do integrador. Para rotação, emita outra e depois revogue a antiga.','Abra <b>/api-docs</b> na sua instalação. Há OpenAPI 3.1 e exemplos em cURL, JavaScript e Python no repositório.','Cadastre um webhook HTTPS para eventos. Guarde o segredo HMAC e verifique assinatura, timestamp e ID do evento. O destinatário precisa deduplicar.'])
p('Escritas exigem Idempotency-Key. Bots retornam 202 e um ID para acompanhamento. Repetir a chave com outro corpo gera conflito; timeout não deve disparar uma nova execução automaticamente.','small')
title(0,'Backup e manutenção','backup')
sub('Copiar seus dados')
steps(['Pause o atendimento e as entradas dos canais. Pare QR/transporte para não gravar durante a cópia. Preserve os diários.','Na pasta Wabotia, execute o comando. Use o arquivo de configuração da implantação correta.'])
code('node scripts/backup.mjs wrangler.production.local.json backup-seguro')
p('O backup inclui banco e mídias. Só considere concluído quando manifest.json tiver <b>complete: true</b>. Guarde a pasta protegida e a <b>MASTER_KEY original separadamente</b>. Depois retome os canais.')
sub('Restaurar em recursos novos')
p('Crie um D1 vazio e um R2 privado novo. Faça uma configuração local apontando para esses recursos, sem sobrescrever a produção. Então execute:')
code('node scripts/restore.mjs wrangler.restore.local.json backup-seguro --empty-target')
p('O script recusa banco preenchido. Configure a MASTER_KEY original, publique a mesma versão e teste dados e arquivos antes de mover o domínio. Pare a instalação antiga antes de ligar os mesmos canais na restaurada.')
sub('Diagnóstico')
code('node scripts/diagnose.mjs https://SUA_URL')
table([['Sintoma','O que conferir'],['Hermes offline','Plugin: gateway do Hermes ligado e reiniciado após a instalação. Túnel: processo, portas, Access, URLs e chaves.'],['401 / 403 / 404','Validade da chave, permissões, perfil e dono do recurso.'],['429','Respeite Retry-After e reduza a frequência.'],['unknown','Confira Hermes/canal e use Execuções ou Entregas para reconciliar.']])
title(0,'Antes de atender clientes','homologar')
p('O núcleo e a publicação já foram testados. Seus perfis e canais precisam passar por homologação com credenciais e destinatários autorizados. Não confunda uma tela de demonstração com um canal conectado.')
sub('Execute na sua instalação de teste')
steps(['Envie e receba texto e anexo em cada canal escolhido. Confira protocolo, prazo, consentimento, avaliações, presença, notas e transferência.','Peça uma resposta lenta ao bot e assuma no meio da execução. A resposta automática antiga não deve chegar ao cliente.','Desligue e religue o Hermes e os conectores. O painel deve continuar acessível; confira a retomada e os estados sem confirmação.','Repita uma mensagem/webhook de teste. Confira deduplicação, assinatura e recuperação. Teste também uma chave expirada/revogada.','Valide backup e restauração antes de depender da instalação. Só então ative o atendimento para clientes.'])
box('<b>Evidência desta edição (0.16.1):</b> 584 testes automatizados, instalação real pelo navegador em outra conta Cloudflare seguida de atualização pelo painel, e plugin validado em um Hermes Agent 0.22.6 em Docker na Hostinger até o bot responder mensagens reais de WhatsApp. <b>Ainda sem validação em uso real:</b> parada de execução, aprovação de ferramenta e artefatos pelo plugin, Hermes fora do Docker e com vários perfis. Isso não substitui a homologação na sua instalação.')
sub('Onde encontrar os detalhes')
p(link('Site e guia atualizado','https://wabotia.queven.app/install')+' · '+link('Plugin do Hermes: contrato e validação','https://github.com/Quevenapp/Wabotia/blob/main/docs/HERMES-PLUGIN.md'))
p(link('Código aberto e instruções completas','https://github.com/Quevenapp/Wabotia'))
p(link('Matriz de validação e limites','https://github.com/Quevenapp/Wabotia/blob/main/docs/VALIDACAO.md'))
p(link('Operação, atualização e recuperação','https://github.com/Quevenapp/Wabotia/blob/main/docs/OPERACAO.md'))
p('Uma organização por implantação. Fuso America/Sao_Paulo. O histórico antigo não é importado automaticamente. Telas novas capturadas em 13/11/2026; as demais são de versões anteriores e podem diferir do painel atual. Menus de fornecedores podem mudar. Wabotia é independente de Cloudflare, Meta e NousResearch.','small')
title(0,'Atualize pelo painel','atualizar')
shot('61-sistema.jpg','Gestão > Sistema e atualizações, em uma instalação local de demonstração na versão 0.16.1.',width=CW)
steps(['O instalador já habilita a atualização. Entre como administrador e abra <b>Gestão &gt; Sistema &gt; Sistema e atualizações</b>. Faça backup antes de publicar uma nova versão.','Clique <b>Verificar atualização</b>. O painel consulta as versões oficiais publicadas; um commit no GitHub só fica disponível quando seu pacote é publicado.','Se houver uma versão nova, clique <b>Atualizar Wabotia</b>. O painel acompanha a preparação dos arquivos, as migrações e a publicação.','Espere <b>Atualização publicada e verificada</b>. Clique <b>Reabrir painel atualizado</b>. Banco, mídias, domínios e credenciais são preservados.'])
p('Em <b>Atualizações automáticas</b>, na mesma tela, você pode deixar o Wabotia instalar as versões novas sozinho em uma janela diária. Você não precisa sincronizar uma cópia GitHub, configurar Builds nem criar Deploy Hook.','small')
p('O plugin do Hermes é atualizado separadamente: gere um novo comando no cartão da conexão e execute de novo na máquina do Hermes quando uma versão pedir.','small')
title(0,'Renove o token quando precisar','renovar')
p('Se o token inicial expirar ou você quiser reduzir suas permissões, crie outro token na mesma conta Cloudflare. Depois da instalação, a atualização precisa somente de <b>Account > Workers Scripts > Edit</b>.')
steps(['Na Cloudflare, abra <b>My Profile > API Tokens > Create Token > Custom Token</b>. Adicione Workers Scripts: Edit e restrinja à conta da instalação.','No Wabotia, abra <b>Gestão &gt; Sistema e atualizações &gt; Alterar configuração de atualização</b>.','Cole o token no campo protegido e clique <b>Verificar e salvar token</b>. O Wabotia confirma se o Worker é desta instalação antes de guardar a credencial criptografada.','Depois de confirmar o novo token, revogue o anterior na Cloudflare se ele não for usado por outro serviço. Atualize também sua anotação privada do token.'])
box('<b>Não troque MASTER_KEY para renovar o token.</b> Essa chave protege credenciais já guardadas no banco. O token de atualização e o token de deploy da configuração Hermes têm finalidades diferentes.')
sub('Onde ver o andamento')
p('Na Cloudflare, abra <b>Workers &amp; Pages > seu Worker > Deployments / Implantações</b>. A versão do Wabotia também aparece em <b>SUA_URL/api/health</b>. As novas instalações publicam diretamente, sem uma compilação em Builds.')
p(link('Documentação de atualização e recuperação','https://github.com/Quevenapp/Wabotia/blob/main/docs/ATUALIZACOES.md'))
title(0,'Reinstalação e recuperação','reinstalar')
sub('Sair de uma instalação antiga')
steps(['Faça backup do banco, arquivos e credenciais da instalação antiga se precisar preservar o histórico. A nova instalação começa vazia.','Instale de novo pelo navegador, página {pg:instalar}, com <b>outro nome</b>. Crie seu administrador e conecte o Hermes: pelo plugin, gere um comando na instalação nova e execute na máquina do Hermes; o vínculo passa a apontar para ela.','Mantenha os canais da instalação nova pausados durante a preparação. Antes de transferir um número ou bot, pause a instalação antiga e confira as entregas pendentes.','Atualize os webhooks dos canais para a URL da nova instalação. Teste atendimento humano, bots e anexos antes de ativar. Nunca use dois consumidores ativos para o mesmo número.','Só depois de validar a nova instalação considere remover o Worker e os recursos antigos ou a cópia particular do GitHub. A nova instalação não depende deles.'])
sub('A atualização ficou sem confirmação')
p('Confira Implantações e /api/health. Um pedido pode ter sido aceito antes de a conexão cair. Não repita enquanto houver publicação em andamento. Após falha confirmada ou 15 minutos sem confirmação, o painel permite liberar nova tentativa, exigindo conferir que a anterior terminou.')
box('Não restaure apenas o código se uma migração exigir outro esquema de banco. Use o backup e revise a compatibilidade. O instalador não substitui outro Worker nem troca as chaves de uma instalação existente.')
p('O instalador pelo navegador foi exercitado com recursos reais na Cloudflare. No instalador pelo terminal, os comandos Windows/macOS estão documentados e ainda precisam de validação nesses sistemas. Teste canais reais na sua instalação antes de usar em produção.','small')
title(0,'Seus contatos','agenda')
p('Guarde nome, telefone, e-mail, empresa e observações de cada cliente. Abra a área <b>Contatos</b>, na coluna da esquerda.')
shot('63-contatos.jpg','Contatos em uma instalação de demonstração. Todos os nomes e telefones desta imagem são fictícios.',width=430)
steps(['Clique em <b>Novo contato</b>. Preencha o nome; os outros campos são opcionais.','No telefone, inclua DDI e DDD: por exemplo, <b>5511999990000</b>. Pode usar +55 (11) 99999-0000. O sistema guarda os dígitos, sem acrescentar o país.','Clique em <b>Salvar contato</b>. Para corrigir, clique no nome na lista. A edição vale para todas as conversas vinculadas.','Para localizar uma pessoa, digite nome, telefone, e-mail ou empresa e clique em <b>Buscar</b>. Use Próxima página quando houver mais registros.'])
p('Atendentes acessam apenas seus perfis. Integrações externas possuem cadastros separados, identificados como Integração externa. A API da agenda também está disponível.','small')
title(40,'Importe sua planilha CSV')
steps(['Na agenda, clique em <b>Modelo CSV</b>. Abra no Excel, LibreOffice ou Google Planilhas. Mantenha a primeira linha e substitua o contato de exemplo.','Use as colunas <b>nome, telefone, email, empresa, observacoes</b>. Só nome é obrigatório. Antes de preencher, formate a coluna telefone como <b>Texto</b>; inclua DDI e DDD.','Salve como <b>CSV UTF-8</b> com vírgula ou ponto e vírgula. No Excel: Arquivo > Salvar como > CSV UTF-8. No Google Planilhas: Arquivo > Fazer download > Valores separados por vírgulas. No LibreOffice: Texto CSV, UTF-8.','Use até <b>500 contatos e 1 MB por arquivo</b>. Para mais contatos, divida a planilha e mantenha o cabeçalho em cada arquivo.','Clique em <b>Importar CSV</b> e escolha o arquivo. Confira os novos contatos, linhas idênticas ignoradas e erros. Corrija os erros, salve e selecione o arquivo novamente.','Com a prévia correta, clique em <b>Importar N contato(s)</b>. Aguarde a confirmação na agenda.'])
shot('24-agenda-csv.jpg','Prévia com dois contatos novos e uma linha idêntica ignorada. Role a janela para conferir as linhas e o botão de importação.',width=460,crop=(295,35,850,490))
p('<b>Se houver erro, nenhum contato será importado.</b> Repetir o mesmo CSV ignora as linhas idênticas, sem sobrescrever edições posteriores. Dados diferentes geram outro cadastro, mesmo com o mesmo telefone. Para corrigir um cadastro existente, edite na agenda.','small')
title(41,'Salve o contato da conversa')
shot('25-agenda-conversa.jpg','Escolha explícita de um contato já cadastrado. Tela com dados fictícios.',width=300,crop=(443,32,555,583))
steps(['Abra <b>Conversas</b> e selecione o atendimento. Clique em <b>Salvar contato</b>. O telefone é preenchido quando está disponível.','Escolha <b>Criar novo contato</b> e preencha o nome, ou <b>Vincular contato existente</b> e selecione a pessoa na agenda. Clique em Salvar contato ou Vincular contato.','O nome passa a aparecer na conversa. Depois, use <b>Editar contato</b> para corrigir os dados.','Se vinculou a pessoa errada, clique em <b>Editar contato > Desvincular desta conversa</b>. O cadastro e o histórico permanecem salvos. Depois escolha o contato correto.'])
box('Um contato pode ser vinculado a várias conversas. O mesmo telefone não une clientes automaticamente. Importar ou salvar contatos não envia mensagens nem concede consentimento.')
p(link('Guia da agenda no site','https://wabotia.queven.app/install#agenda')+' · '+link('Baixar modelo CSV','https://wabotia.queven.app/modelo-contatos.csv'),'small')

title(0,'Atualize o WhatsApp do Wabotia','whats')
p('O painel na Cloudflare e os conectores externos são atualizados separadamente. Preserve as sessões e os diários de entrega. A conexão oficial agora usa a Zernio; as antigas conexões diretas da Meta permanecem pausadas até a substituição.')
steps(['Faça backup. No painel, abra <b>Gestão &gt; Sistema e atualizações &gt; Verificar atualização &gt; Atualizar Wabotia</b>. Espere a confirmação e reabra o painel.','Se usava <b>Meta direto</b>, cadastre a conta e o webhook Zernio conforme este guia. Reconcilie as entregas anteriores antes de ativar a nova linha.','Se usa <b>QR direto</b>, pause a conexão, confira as entregas e pare o conector. Faça backup privado de .env e data/ (ou volume Docker). Atualize a cópia do repositório oficial e reinstale as dependências na pasta connectors/qr.','Se usa <b>WhatsApp pelo Hermes</b>, atualize o transporte e a extensão compatível com o gateway parado. Preserve os perfis, bots e dados.'])
table([['Seu modo','Depois de atualizar o código'],['QR com Node.js','Na pasta connectors/qr: npm ci e npm start. Use a mesma pasta de dados e as mesmas credenciais.'],['QR com Docker','docker compose stop; faça backup; atualize o código; docker compose up -d --build. Não use down -v.'],['Pelo Hermes','Siga o roteiro específico; não aplique patches à força nem substitua o perfil inteiro.']])
p(link('Roteiro de atualização QR','https://github.com/Quevenapp/Wabotia/blob/main/connectors/qr/README.md#atualizar-sem-perder-a-sessão')+'<br/>'+link('Roteiro de atualização Hermes','https://github.com/Quevenapp/Wabotia/blob/main/connectors/hermes/README.md#atualização-050'))
box('O botão do painel não atualiza o computador/VPS. Reative a conexão somente após atualizar o conector. Não execute duas cópias para o mesmo número. Se não souber qual processo usa, confira Hermes e canais antes de prosseguir.')

title(43,'Fotos, vídeos e documentos')
shot('26-whatsapp-midias.jpg','Conversa local de teste: imagem, áudio e resposta citada. Todos os dados são fictícios.',width=380,crop=(585,300,850,820))
steps(['Em <b>Conversas</b>, abra o atendimento e clique <b>Assumir conversa</b>. Isso pausa a IA e invalida respostas antigas ainda em preparação.','Clique <b>Anexar</b>, escolha os arquivos e escreva a legenda se quiser. Deixe Automático pelo arquivo ou selecione Enviar como documento.','Clique <b>Enviar</b> e acompanhe a porcentagem. Na fila significa pedido recebido; Enviada significa confirmação do provedor. Entregue e Lida dependem dos recibos do canal.','Reproduza vídeo/áudio recebido no painel. Clique no nome do arquivo para baixar. A seta na mensagem permite responder citando o conteúdo.'])

title(44,'Áudio e limites dos arquivos')
sub('Grave uma mensagem de voz')
steps(['Assuma a conversa e clique <b>Gravar áudio</b>. Permita o microfone no navegador. Use o painel em HTTPS.','Grave por até dois minutos e clique em parar. Ouça a prévia. Você pode descartar antes de enviar.','Clique <b>Enviar</b>. A gravação é preparada em OGG/Opus, formato compatível com voz no WhatsApp.'])
table([['Conteúdo','Limites de envio'],['Foto','Zernio: JPG/PNG até 5 MB. QR direto: até 20 MB.'],['Vídeo','Zernio: MP4/3GP até 16 MB, H.264/AAC. QR direto: até 100 MB; prefira MP4 compatível.'],['Áudio e voz','Zernio até 16 MB; voz em OGG/Opus. QR: arquivo de áudio até 100 MB, voz até 16 MB.'],['Documento','Até 100 MB. Na Zernio, use PDF, TXT ou formatos Office aceitos.'],['Figurinha','Envio indisponível pela Zernio nesta integração. QR: WebP 512 x 512 pixels até 1 MB.']])
p('O upload Wabotia aceita até 100 MB, mas o canal pode aceitar menos. Não há conversão automática de vídeo/documento. O formato e o codec ainda precisam ser aceitos pelo WhatsApp. O transporte Hermes pode oferecer menos funções, conforme o adaptador instalado.','small')
sub('Outras ações da mensagem')
p('Reaja pelo ícone de rosto. Editar e Apagar aparecem quando o canal permite; a Meta não oferece essas ações neste fluxo. No QR, edição de texto tem limite local de 15 minutos. Localização e Compartilhar contato estão no seletor de conteúdo.')
box('Se aparecer <b>Sem confirmação</b>, confira Entregas e o WhatsApp antes de reenviar. A conexão pode ter caído depois de o provedor aceitar. Uploads incompletos expiram após 24 horas; o rascunho permanece em caso de erro enquanto a conversa está aberta.')

title(45,'Converse em grupos')
shot('27-whatsapp-grupos.jpg','Menu Grupos WhatsApp com um grupo fictício. O conector QR deve estar ligado para buscar grupos.',width=CW)
steps(['Abra <b>Grupos WhatsApp</b>, selecione a conexão QR e use <b>Buscar grupos</b>. Aguarde o resultado em Operações recentes.','Abra um grupo existente ou selecione Criar grupo / Entrar por convite. Use apenas grupos e participantes autorizados.','Na conversa, escolha a IA: <b>Somente atendimento humano</b>, <b>Quando mencionada ou /bot</b> ou <b>Todas as mensagens</b>. Retome a IA se o atendimento estiver assumido por uma pessoa.','Atualize os dados do grupo antes de mudar nome, participantes ou convite. O número precisa ter as permissões necessárias no próprio WhatsApp. Confira resultados parciais por participante.'])
box('<b>Meta tem regras diferentes:</b> grupos empresariais exigem conta oficial elegível, têm até oito participantes na referência consultada e entrada por convite. Não acessam todos os grupos pessoais. Sem ligações, editar/apagar ou interativos no grupo Meta.')
p('Pelo Hermes, configure também a política normal de grupos dele. Mensagens podem ser filtradas antes de chegar ao Wabotia. O transporte não oferece administração completa de grupos. Grupos não são salvos como uma pessoa na agenda.','small')

title(46,'Ligações e recursos disponíveis')
p('Nesta integração, o Wabotia oferece mensagens, mídias e recibos pela Zernio. Ligações ao vivo no navegador não estão implementadas. O histórico de ligações anteriores permanece disponível.')
box('A Zernio possui recursos próprios de voz, mas eles não equivalem ao antigo WebRTC direto da Meta. Confira os recursos disponíveis no cartão da conexão; não tente reativar a integração antiga.')
p(link('Documentação de voz Zernio','https://docs.zernio.com/platforms/whatsapp/calling'),'small')

title(47,'Excluir um telefone')
steps(['Abra <b>Gestão &gt; Hermes e canais</b> ou <b>Integração Zernio</b> e localize o telefone.','Conclua ou reconcilie envios já iniciados, ligações anteriores e operações de grupos sem confirmação.','Clique <b>Excluir telefone</b> e confira a confirmação. A exclusão cancela mensagens e operações ainda na fila, remove a conexão e suas credenciais locais.','Mensagens, conversas e protocolos permanecem no histórico. Os atendimentos daquela linha são encerrados. Para voltar a atender, conecte novamente e inicie uma nova conversa.'])
box('Excluir no Wabotia não desconecta nem remove a conta WhatsApp na Zernio. Se desejar encerrar também a conexão no provedor, faça isso na Zernio depois de conferir suas pendências.')

title(48,'Teste com seu número real')
p('Os testes automatizados conferem as regras usando serviços simulados. Esta etapa confirma seu número, o conector, a rede e as permissões reais. Use destinatários e grupo de teste autorizados.')
table([['Teste','O que conferir'],['Mídias','Receba e envie foto, vídeo MP4, documento e áudio. Grave voz no painel e ouça nos dois lados.'],['Ações','Cite e reaja; confira recibos. No QR, edite/apague uma mensagem enviada.'],['Reconexão','Desligue e religue o QR. Confira mensagens recebidas enquanto ficou offline, sem duplicação.'],['Grupos','Confira as capacidades do canal antes de testar participantes e automação.'],['Ligações','Somente histórico nesta integração; não tente iniciar chamadas ao vivo no navegador.'],['Responsabilidade','Assuma durante resposta da IA. Nenhuma resposta antiga deve ser enviada depois.'],['API externa','Chave sem permissão recusada; mesma intenção repetida sem duplicar; webhook validado e deduplicado.']])
p('Anote a versão Wabotia, versão Hermes/conector, modo WhatsApp, data e resultado. <b>Na fila não é prova de entrega.</b> Não marque uma função como homologada apenas porque a simulação passou.')
sub('Integrar com outro sistema')
p('Cadastre a aplicação em Sistemas conectados. Selecione somente os perfis e permissões necessários. A API oferece mídias, grupos e chamadas, com chaves individuais. O sistema integrador protege a chave no seu servidor; para voz ele também precisa de um cliente WebRTC.')
p(link('Guia completo WhatsApp','https://wabotia.queven.app/install#whatsapp-recursos')+' · '+link('API e exemplos','https://github.com/Quevenapp/Wabotia/blob/main/docs/API.md#whatsapp-mídias-grupos-e-ligações'))
box('Você pode manter o painel disponível enquanto Hermes/QR estão desligados. Os bots dependem do Hermes ligado; o canal QR depende do seu conector. Cada número deve ter apenas um consumidor ativo.')

title(0,'Seus números, uma entrada','roteador')
p('A <b>Integração Zernio</b> conecta os telefones de um perfil Zernio e distribui as mensagens entre eles. A Zernio intermedeia a integração com a Meta. QR e transporte Hermes continuam separados; não é preciso alterar o Hermes para usar este recurso.')
steps(['Faça backup e atualize o Wabotia pelo painel.','Abra <b>Gestão &gt; WhatsApp e canais &gt; Integração Zernio</b>. Prepare a conta Zernio, o webhook, os números e um grupo conforme as próximas páginas.'])
sub('Atendimento e modelos pagos são diferentes')
table([['Tipo','Como funciona'],['Atendimento','O cliente falou com este mesmo número nas últimas 24 horas. O roteador respeita um teto local de até 1.000 mensagens por número/mês.'],['Modelo pago','Use modelo aprovado pela Meta, autorização explícita naquele envio e prova de consentimento na mesma categoria. A aplicação e a origem também precisam permitir pagos.'],['Novos contatos','O link público do grupo abre o WhatsApp num número ativo com saldo. O cliente inicia a conversa; o link sozinho não envia mensagem.'],['Conversa em andamento','Mantém o remetente original. Fim de cota, pausa ou falha não fazem o sistema enviar por outro número.']])
box('A janela de 24 horas pertence ao cliente e ao número com que ele falou. <b>Saldo em outro telefone não transfere essa janela.</b> O Wabotia não converte atendimento ou notificação automática de um número do roteador em modelo pago.')
p('O contador local é uma estimativa para limitar e distribuir envios. Ele não garante gratuidade nem substitui as faturas da Zernio e Meta. Confira os preços e as condições da sua conta.','small')
p(link('Preços e custos WhatsApp na Zernio','https://docs.zernio.com/platforms/whatsapp/pricing')+' · '+link('Guia do roteador no site','https://wabotia.queven.app/install#roteador'),'small')

title(50,'Cadastre a Zernio e o webhook')
steps(['Crie um perfil na Zernio. Separe o ID do perfil e sua chave API.','No Wabotia, cadastre a conta com nome, ID do perfil Zernio, fuso, chave API e segredo do webhook.','Use <b>Conectar WhatsApp</b> para abrir o cadastro guiado pela Zernio. Ao voltar ao Wabotia, busque os números conectados.','Na Zernio, cadastre o webhook único da conta exibido no Wabotia, com o mesmo segredo e os eventos de mensagens, recibos e reações.'])
code('https://SUA_URL/webhooks/zernio-accounts/ID_DA_CONTA_LOCAL')
box('Use o endereço da sua instalação. A assinatura é validada com o segredo do webhook Zernio. Evite outro sistema respondendo simultaneamente pelo mesmo número.')
p('A chave API Zernio é diferente da chave de integração Wabotia, da senha de login e das chaves Cloudflare. Na edição, omita os segredos para mantê-los.','small')

title(51,'Números e contadores')
shot('29-router-contadores.jpg','Dois números e consumos fictícios. O uso inclui reservas; mensagens pagas e cobrança não informada aparecem separadas.',width=CW)
steps(['Clique <b>Buscar números na Zernio</b> e escolha um número encontrado. Dê um nome para reconhecê-lo.','Confira o consumo já conhecido neste mês. Informe o consumo inicial e o limite local, no máximo <b>1.000</b>. Esse limite não corresponde a uma promessa de gratuidade.','Confirme o uso e o fuso, depois clique <b>Adicionar ao roteador</b>. O número entra pausado. Confira o webhook e clique <b>Ativar</b>. Repita para os demais números do perfil Zernio.','Se o telefone estava em outra conexão, pause-a e reconcilie entregas antes de cadastrar. Use Excluir telefone para remover a conexão antiga preservando o histórico.'])
sub('Leia o uso protegido')
p('<b>Uso = histórico inicial do mês + entregas de atendimento + reservas.</b> Envios humanos, bots e API compartilham a contagem. Falha definitiva ou cancelamento antes do envio libera a reserva. Sem confirmação mantém a reserva, inclusive na mudança de mês.')
box('O mês segue o fuso da conta. Recibos repetidos não somam novamente. Envios feitos fora do Wabotia só aparecem se os recibos chegarem ao webhook; pode haver atraso. <b>Confira também o WhatsApp Manager.</b> Cobrança não informada não significa gratuito.')

title(52,'Grupo e programas autorizados')
shot('31-router-grupo.jpg','Grupo fictício com sorteio, link de entrada e permissão para pedidos pagos. O envio ainda exige autorização individual.',width=CW)
steps(['Abra <b>Criar grupo de roteamento</b>, informe um nome e selecione os números da mesma conta Zernio.','O rodízio prioriza números com saldo no contador local. A escolha vale para novos atendimentos; o remetente depois fica vinculado.','Ative o grupo. Marque <b>Criar link público</b> para divulgar uma entrada única. Para modelos pagos, marque a permissão específica. Salve.','Copie o link público para novos clientes iniciarem contato. Copie o ID do grupo para o seu programa integrador. Um número em vários grupos mantém um só contador.','Em <b>Sistemas conectados</b>, crie a aplicação e sua chave com acesso ao perfil. Em <b>Autorizar programas externos</b>, selecione a aplicação, seus números diretos ou grupos e salve.'])
box('Autorizar um grupo inclui seus membros atuais e futuros. Escolher um número diretamente exige a permissão individual. Ativar modelos pagos nessa tela <b>não autoriza envios automaticamente</b>: cada pedido precisa da confirmação e do consentimento.')
p('A chave da aplicação fica no servidor do programa integrador. Ela não deve aparecer no navegador dos clientes. As credenciais Zernio permanecem protegidas no Wabotia.','small')

title(53,'Envio pago: confirme cada pedido')
p('Para o programa integrador: faça <b>POST /api/v1/profiles/{perfil}/router/messages</b>, com chave Bearer e Idempotency-Key. Escolha <b>number_id</b> ou <b>pool_id</b>. Reutilize external_id para o mesmo cliente/atendimento e origem.')
code('{\n  "pool_id": "ID_DO_GRUPO",\n  "to": "5511999992222",\n  "external_id": "cliente-456",\n  "allow_paid": true,\n  "consent": {\n    "granted": true, "category": "utility",\n    "reference": "Aceite no pedido 456"\n  },\n  "template": {\n    "name": "seu_modelo_aprovado",\n    "language": "pt_BR"\n  }\n}')
p('O exemplo omite variáveis do modelo; se ele tiver campos, envie os componentes correspondentes. Use modelo real aprovado e consentimento na mesma categoria. Não basta ter uma opção geral de pagos ligada. Um consentimento retirado pelo cliente não pode ser substituído por uma declaração da API.','small')
table([['Resultado','O que fazer'],['202 / pending','O pedido entrou na fila. Guarde delivery_id e consulte /router/messages/{delivery_id}.'],['sent','O canal aceitou. Confira provider_status delivered/read para comprovar entrega/leitura.'],['unknown','Sem confirmação. Confira e reconcilie; não gere outro pedido nem troque de número. Nova tentativa paga exige nova autorização.'],['Cota ou janela encerrada','Peça nova mensagem do cliente ou faça um pedido explícito de modelo autorizado. Não há troca silenciosa do remetente.']])
p('Antes de atender clientes, teste os números reais: webhook de cada telefone, remetente escolhido/fixo, cota, modelo autorizado, recibos e repetição da mesma chave sem duplicar. Os testes do projeto usam dados fictícios; não substituem essa homologação.','small')
p(link('Exemplos cURL, JavaScript e Python','https://github.com/Quevenapp/Wabotia/blob/main/docs/ROTEADOR.md')+' · '+link('Documentação interativa','https://wabotia.queven.app/api-docs'),'small')
# Caminhos alternativos
title(0,'Caminhos alternativos','alternativos')
p('As páginas seguintes guardam os dois roteiros anteriores. Eles continuam funcionando e são mantidos para quem já usa ou precisa deles. <b>Quem instalou pelo navegador e ligou o Hermes pelo plugin não precisa de nada daqui.</b>')
table([['Roteiro','Quando usar','Páginas'],['Instalador pelo terminal','Você prefere que o token da Cloudflare fique só no seu computador, ou quer retomar uma instalação feita assim. Exige Node.js.','{pg:terminal} a {pg:terminal-fim}'],['Hermes por túnel Cloudflare','Seu Hermes já está ligado por URLs públicas, ou o plugin não pode ser instalado na máquina. Exige domínio na Cloudflare, Zero Trust, Access e cloudflared.','{pg:tunel} a {pg:tunel-fim}']],widths=[CW*.26,CW*.54,CW*.20])
box('Os dois caminhos chegam ao mesmo painel. A instalação pelo terminal e a instalação pelo navegador publicam o mesmo pacote oficial e recebem as mesmas atualizações. Uma conexão Hermes por túnel e outra por plugin usam os mesmos bots.')
title(0,'Terminal: prepare o Node.js no Ubuntu','terminal')
p('Este roteiro é a alternativa ao instalador pelo navegador da página {pg:instalar}. <b>Node.js executa o instalador; npm vem junto.</b> Você pode publicar a partir do computador ou da VPS. O Wabotia fica na Cloudflare. Se usar a VPS, a pasta privada com as chaves ficará nela.')
sub('1. Abra o terminal certo')
steps(['Hostinger: abra <b>VPS</b>, selecione o servidor e procure <b>Terminal</b> ou <b>Terminal do navegador</b>. Use o Ubuntu da VPS, fora do contêiner Docker do Hermes.','Ubuntu local: abra <b>Terminal</b>. Windows/WSL2: abra o aplicativo <b>Ubuntu</b> no menu Iniciar. Para Windows sem WSL ou macOS, use a página {pg:node-winmac}.','Digite o comando abaixo e pressione Enter. Ele informa qual usuário está executando os comandos.'])
code('whoami')
sub('2. Instale os pacotes necessários')
p('Se a resposta foi <b>root</b>, como costuma acontecer na VPS Hostinger:')
code('apt-get update\napt-get install -y ca-certificates curl git libatomic1')
p('Se apareceu <b>outro nome</b>, use esta alternativa com sudo:')
code('sudo apt-get update\nsudo apt-get install -y ca-certificates curl git libatomic1')
box('Use somente a alternativa do seu usuário. <b>libatomic1</b> evita o erro libatomic.so.1. A senha de sudo não aparece enquanto você digita. Se houver erro, corrija antes de seguir.')
p('Cole uma linha de cada vez. Espere o nome do usuário reaparecer antes da próxima. Copie apenas os comandos, sem root@servidor:~#. Não use apt-get no macOS.','small')
title(0,'Instale Node.js e confira','node2')
sub('3. Instale o NVM e a versão LTS')
p('No mesmo terminal Ubuntu e com o mesmo usuário da página anterior, execute uma linha de cada vez. NVM gerencia as versões do Node.js. O primeiro comando usa o instalador oficial. O download pode levar alguns minutos.')
code('curl -fsSL https://raw.githubusercontent.com/nvm-sh/nvm/v0.41.0/install.sh | bash\nsource "$HOME/.nvm/nvm.sh"\nnvm install --lts\nnvm alias default \'lts/*\'\nnvm use --lts')
p('LTS é a versão com suporte prolongado. Copie a linha source inteira, incluindo as duas aspas. Se o NVM disser que já está instalado, siga com as linhas seguintes. Não use sudo antes de nvm ou node.','small')
sub('4. Veja os dois resultados')
code('node -v\nnpm -v')
p('<b>Exemplo de saída, não são comandos para copiar:</b>')
code('v26.13.0\n11.20.0')
p('Os números podem mudar. O Wabotia exige <b>Node.js 22.13 ou superior</b> e npm. Os dois comandos precisam mostrar as versões sem erro. Se houver erro, use a próxima página.')
box('Node.js instalado por NVM fica disponível para este usuário. Continue o instalador Wabotia no <b>mesmo terminal e usuário</b>, sem sudo. Instalar como root não instala automaticamente para o usuário hermes.')
p('Com os dois resultados corretos, ative o R2 como na página {pg:r2}, crie o token na página {pg:terminal-token} e execute o instalador na página {pg:terminal-instalar}.')
p(link('Abrir o passo a passo com botões de copiar','https://wabotia.queven.app/install#nodejs')+' · '+link('NVM oficial','https://github.com/nvm-sh/nvm/tree/v0.41.0'),'small')
title(0,'Node.js: resolva os erros','node-erros')
sub('libatomic.so.1: cannot open shared object file')
p('O Node.js foi instalado, mas falta uma biblioteca do Ubuntu. Repita a preparação da página {pg:terminal} conforme seu usuário. Se já fez apt-get update, o comando de correção como root é:')
code('apt-get install -y libatomic1\nnode -v\nnpm -v')
p('Com usuário comum, coloque sudo somente antes de apt-get. Não precisa apagar o Node.js nem o Wabotia.','small')
sub('nvm: command not found ou node: command not found')
p('Entre no Ubuntu com o mesmo usuário usado para instalar e execute:')
code('source "$HOME/.nvm/nvm.sh"\nnvm use --lts\nnode -v\nnpm -v')
p('Se o arquivo nvm.sh não existir, volte à etapa 3 da página {pg:node2}. Se estiver no Windows ou Mac, conclua o instalador gráfico e abra uma nova janela de terminal.','small')
sub('O terminal mostra somente >')
p('Geralmente faltou fechar uma aspa. Pressione <b>Ctrl+C</b> e copie novamente a linha inteira. A linha source precisa de uma aspa antes de $HOME e outra depois de nvm.sh.')
sub('Falta de permissão ou bloqueio do npm.ps1')
p('No Ubuntu, confira <b>whoami</b>: usuário comum precisa de sudo para apt-get; root não precisa. Se sua conta não puder usar sudo, use uma conta administradora. No PowerShell, confira o npm com <b>npm.cmd -v</b>.')
box('Não avance enquanto node e npm não responderem com números de versão. O erro de biblioteca acontece antes da instalação do Wabotia; não exige apagar recursos da Cloudflare.')
title(0,'Node.js no Windows e Mac','node-winmac')
sub('Windows sem WSL2: instalador gráfico')
steps(['Abra '+link('nodejs.org/en/download','https://nodejs.org/en/download')+'. Escolha <b>LTS</b> e <b>Windows</b>. Baixe <b>Windows Installer (.msi)</b>.','Em um PC Intel/AMD comum, selecione x64. Use ARM64 somente se o seu computador for ARM. Não copie os comandos Linux/NVM da página.','Abra o arquivo baixado, avance pelo assistente e mantenha <b>npm</b> e <b>PATH</b> nas opções padrão. Conclua.','Feche terminais antigos e abra uma nova janela de <b>PowerShell</b> pelo menu Iniciar. Confira:'])
code('node -v\nnpm.cmd -v')
p('Se usa Ubuntu/WSL2 para executar o instalador, siga as páginas {pg:terminal} e {pg:node2} dentro do aplicativo Ubuntu. Instalar no Windows não substitui essa preparação.','small')
sub('macOS: instalador gráfico')
steps(['No mesmo site oficial, escolha <b>LTS</b>, <b>macOS</b> e baixe <b>macOS Installer (.pkg)</b> para o seu Mac.','Abra o arquivo e conclua o assistente com as opções padrão. Ele instala Node.js e npm.','Feche terminais antigos. Abra <b>Aplicativos > Utilitários > Terminal</b> e confira:'])
code('node -v\nnpm -v')
